import axios from "axios";
import React, { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";

export default function EditCategory() {
    const [category, setCategory] = useState({
        name: "",
    })
    const {id} = useParams();
    const navigate = useNavigate();
    
    const fetchCategory = async(id) => {
        try {
        const token = localStorage.getItem("token");
        const res = await axios.get(
            `http://localhost:5000/api/v1/categories/${id}`,
            category,
            {
                headers: {
                    Authorization: `Bearer ${token}`
                },
            }
        )
        setCategory(res.data.data)
    } catch(err) {
       console.log(err.response?.data || err.message);
    }
}

const handleChange = (e) => { setCategory({ ...category, [e.target.name]: e.target.value, }); };

   useEffect((id) => {
    fetchCategory(id);
   }, [id])

   const updateCategory = async(id) => {
    try {
        const token = localStorage.getItem("token");
        const res = await axios.put(
            `http://localhost:5000/api/v1/categories/${id}`,
            {
                headers: {
                    Authorization: `Bearer ${token}`
                }
            }
        )
         console.log(res.data)
            alert("Order Update Successfully")
        } catch (err) {
            console.log(err.response?.data || err.message);
            alert("Update Failed");
        }
    }
   
    return (
        <>
        <div className="container mt-5">
            <div className="card shadow mb-4">
                <h4 className="text-center">Edit Category</h4>
                <input type="text" className="form-control" value={category.id || ""} onChange={handleChange} />

                <button className="btn btn-primary" onClick={updateCategory} > Update Category </button>
            </div>
        </div>
        </>
    )
}
